package extern

import (
	"fmt"
	"go/format"
	"go/types"
	"sort"
	"strconv"
	"strings"
)

// Method describes a callable exported method. Receiver is the exported type
// (or its pointer), including when the method is promoted from an embedded type.
// The signature excludes the receiver from its ordinary parameters.
type Method struct {
	TypeName  string
	Name      string
	Receiver  types.Type
	Signature *types.Signature
}

func exportedMethods(pkg *types.Package) []Method {
	var methods []Method
	for _, name := range pkg.Scope().Names() {
		obj, ok := pkg.Scope().Lookup(name).(*types.TypeName)
		if !ok || !obj.Exported() || obj.IsAlias() {
			continue
		}
		named, ok := obj.Type().(*types.Named)
		if !ok {
			continue
		}
		seen := make(map[string]bool)
		// Prefer the value receiver when both method sets contain a method.
		for _, receiver := range []types.Type{named, types.NewPointer(named)} {
			set := types.NewMethodSet(receiver)
			for i := range set.Len() {
				method := set.At(i).Obj().(*types.Func)
				if !method.Exported() || seen[method.Name()] {
					continue
				}
				seen[method.Name()] = true
				methods = append(methods, Method{
					TypeName: name, Name: method.Name(), Receiver: receiver,
					Signature: method.Type().(*types.Signature),
				})
			}
		}
	}
	sort.Slice(methods, func(i, j int) bool {
		if methods[i].TypeName != methods[j].TypeName {
			return methods[i].TypeName < methods[j].TypeName
		}
		return methods[i].Name < methods[j].Name
	})
	return methods
}

// BindMethods appends handle declarations and method externs to Bind's output,
// and emits the corresponding Go package-level shims. Only the receiver is
// erased; all other arguments and results retain their natural Go ABI.
func BindMethods(pkg *Package, options BindOptions, shimPath, shimPackage string) (string, []byte, error) {
	var declarations, body strings.Builder
	imports := make(map[string]string)
	qualifier := func(pkg *types.Package) string {
		if pkg.Path() == shimPath {
			return ""
		}
		if alias, ok := imports[pkg.Path()]; ok {
			return alias
		}
		alias := fmt.Sprintf("go%d", len(imports))
		imports[pkg.Path()] = alias
		return alias
	}
	handles := make(map[string]bool)
	for _, method := range pkg.Methods {
		params, result, reason := bindingTypes(method.Signature, options.Float)
		// A promoted nongeneric method can belong to a generic receiver.
		receiver := method.Receiver
		if ptr, ok := receiver.(*types.Pointer); ok {
			receiver = ptr.Elem()
		}
		if receiver.(*types.Named).TypeParams().Len() != 0 {
			reason = "generic function"
		}
		if iface, ok := receiver.Underlying().(*types.Interface); ok && !iface.IsMethodSet() {
			// Constraint-only interfaces cannot be used as runtime receivers.
			reason = "generic function"
		}
		name, nameReason := bindingName(method.TypeName+method.Name, options.Prefix)
		if reason == "" {
			reason = nameReason
		}
		if reason != "" {
			fmt.Fprintf(&declarations, "// skipped: %s.%s (%s)\n", method.TypeName, method.Name, reason)
			continue
		}
		if !handles[method.TypeName] {
			fmt.Fprintf(&declarations, "\ntype %s = %sHandle\n", method.TypeName, method.TypeName)
			handles[method.TypeName] = true
		}
		if options.Prefix == "" && options.Prelude[name] {
			fmt.Fprintf(&declarations, "// collides with prelude: %s\n", name)
		}
		shimName := method.TypeName + "_" + method.Name
		fmt.Fprintf(&declarations, "extern func %s(recv %s", name, method.TypeName)
		for i, param := range params {
			fmt.Fprintf(&declarations, ", p%d %s", i, param)
		}
		fmt.Fprintf(&declarations, ") %s = %s.%s\n", result, strconv.Quote(shimPath), shimName)

		imports["fmt"] = "gofmt"
		fmt.Fprintf(&body, "func %s(recv any", shimName)
		for i := range method.Signature.Params().Len() {
			fmt.Fprintf(&body, ", p%d %s", i, types.TypeString(types.Unalias(method.Signature.Params().At(i).Type()), qualifier))
		}
		body.WriteString(") ")
		if method.Signature.Results().Len() > 1 {
			body.WriteByte('(')
		}
		for i := range method.Signature.Results().Len() {
			if i != 0 {
				body.WriteString(", ")
			}
			body.WriteString(types.TypeString(types.Unalias(method.Signature.Results().At(i).Type()), qualifier))
		}
		if method.Signature.Results().Len() > 1 {
			body.WriteByte(')')
		}
		body.WriteString(" {\n")
		fmt.Fprintf(&body, "receiver, ok := recv.(%s)\n", types.TypeString(method.Receiver, qualifier))
		fmt.Fprintf(&body, "if !ok { panic(gofmt.Sprintf(%q, recv)) }\n", "gofx shim: "+shimName+": receiver is <%T>")
		fmt.Fprintf(&body, "return receiver.%s(", method.Name)
		for i := range method.Signature.Params().Len() {
			if i != 0 {
				body.WriteString(", ")
			}
			fmt.Fprintf(&body, "p%d", i)
		}
		body.WriteString(")\n}\n\n")
	}
	var source strings.Builder
	fmt.Fprintf(&source, "// Code generated by gofx bind %s --shim. DO NOT EDIT.\npackage %s\n\n", pkg.Path, shimPackage)
	if len(imports) != 0 {
		source.WriteString("import (\n")
		paths := make([]string, 0, len(imports))
		for path := range imports {
			paths = append(paths, path)
		}
		sort.Strings(paths)
		for _, path := range paths {
			fmt.Fprintf(&source, "%s %q\n", imports[path], path)
		}
		source.WriteString(")\n\n")
	}
	source.WriteString(body.String())
	formatted, err := format.Source([]byte(source.String()))
	if err != nil {
		return "", nil, fmt.Errorf("format method shim: %w", err)
	}
	return declarations.String(), formatted, nil
}
